function login(b) {
  if (b == undefined) return true;
  info = result
  so = source.key
  pw = info.密码
  key=java.get(source.key,{}).cookies().toString()
  if (b) {
    url = so + 'api/user/login,'
    body = `account=${info.用户名}&password=${pw}&appuuid=`  } 
  post = JSON.stringify({
    "body": String(body),
    "method": "POST"
  })
  url += post
  java.log(url)
  result = java.ajax(url)
  if (result.match(/ok/)) {
    java.log(result);
    java.toast('登录成功' + info["用户名"]); 
    c = cookie.getCookie(source.key)
    source.putLoginHeader(c);
  } else {
    java.toast('登录失败');
}}
