ruleContent.content:
@js:
if (/baidu.com/.test(baseUrl)) {
    pre = baseUrl.replace("baidu", "chiuhagi");
    rev = org.jsoup.Jsoup.parse(java.ajax(pre));
    url = source.key + rev.select('#linkPrev').attr('href');
    java.setContent(result = java.ajax(url));
} else if (/bing.com/.test(baseUrl)) {
    nex = baseUrl.replace("cn.bing", "www.chiuhagi");
    var flag = true;
    while (flag) {
    next = org.jsoup.Jsoup.parse(java.ajax(nex));
    nexUrl = source.key + next.select('#linkNext').attr('href');
      flag = /_\d+\.html$/.test(nexUrl);
      if (flag) {
        nex = nexUrl;
      }
    }
    java.setContent(result = java.ajax(nex));
  } else { result; }
result = java.getString('#booktxt@p@html');

